{
  "manifest_schema": 1,
  "id": "vendor.semantic",
  "version": "1.0.0",
  "display_name": "Semantic continuation fixture",
  "host_api": {
    "minimum": "0.0.1",
    "maximum": "99.0.0"
  },
  "protocol": 1,
  "provider": {
    "mode": "persistent",
    "binaries": {
      "aarch64-apple-darwin": "bin/provider",
      "x86_64-unknown-linux-gnu": "bin/provider"
    }
  },
  "actions": [
    {
      "id": "vendor.semantic.open",
      "label": "Open semantic review",
      "description": "Open the typed semantic relationship review",
      "category": "vendor.semantic",
      "contexts": [
        "dashboard"
      ],
      "arguments": [],
      "timeout_seconds": 60,
      "destructive": false,
      "confirmation": "none",
      "handler": "open",
      "allowed_outcomes": [
        "navigate-declared-route"
      ]
    },
    {
      "id": "vendor.semantic.deploy",
      "label": "Deploy selected resource",
      "description": "Exercise typed context and stale destructive continuation",
      "category": "vendor.semantic",
      "contexts": [
        "dashboard"
      ],
      "arguments": [],
      "timeout_seconds": 60,
      "destructive": true,
      "confirmation": "provider-continuation",
      "handler": "deploy",
      "allowed_outcomes": [
        "request-host-confirmation",
        "notice"
      ]
    }
  ],
  "panels": [
    {
      "id": "vendor.semantic.list",
      "model_kinds": [
        "list"
      ],
      "event_schema": [
        {
          "kind": "selected",
          "arguments": []
        }
      ],
      "handler": "semantic-list",
      "ports": []
    },
    {
      "id": "vendor.semantic.detail",
      "model_kinds": [
        "list"
      ],
      "event_schema": [],
      "handler": "semantic-detail",
      "ports": []
    }
  ],
  "routes": [
    {
      "id": "vendor.semantic.open",
      "activation_fields": [],
      "target_screen": "vendor.semantic.review"
    }
  ],
  "screens": [
    {
      "path": "screens/main.screen.toml",
      "screen_ids": [
        "vendor.semantic.review"
      ]
    }
  ]
}
